<?php
require_once '../../config/auth.php';
requestMethod('GET');
requireAdmin();
try{ $db=getDB(); $where=[];$params=[]; if(!empty($_GET['type'])&&$_GET['type']!=='all'){$where[]='al.action_type LIKE ?';$params[]='%'.trim($_GET['type']).'%';} $whereSql=$where?'WHERE '.implode(' AND ',$where):''; $page=max(1,(int)($_GET['page']??1)); $limit=min(100,max(1,(int)($_GET['limit']??20))); $offset=($page-1)*$limit; $stmt=$db->prepare("SELECT COUNT(*) c FROM activity_log al $whereSql"); $stmt->execute($params); $total=(int)$stmt->fetch()['c']; $sql="SELECT al.*, u.full_name AS user_name, u.email FROM activity_log al LEFT JOIN users u ON u.id=al.user_id $whereSql ORDER BY al.created_at DESC LIMIT :limit OFFSET :offset"; $stmt=$db->prepare($sql); foreach($params as $i=>$v)$stmt->bindValue($i+1,$v); $stmt->bindValue(':limit',$limit,PDO::PARAM_INT); $stmt->bindValue(':offset',$offset,PDO::PARAM_INT); $stmt->execute(); $activities=array_map(fn($a)=>['id'=>(int)$a['id'],'user_id'=>$a['user_id']?(int)$a['user_id']:null,'user_name'=>$a['user_name']?:'System','email'=>$a['email'],'action_type'=>$a['action_type'],'description'=>$a['description'],'created_at'=>$a['created_at']],$stmt->fetchAll()); jsonResponse(['success'=>true,'activities'=>$activities,'total'=>$total,'page'=>$page,'limit'=>$limit]); }catch(Throwable $e){ jsonError('Could not fetch activity.',500); }
